INSERT INTO `test_results` (`id`, `test_id`, `title`, `description`, `image_path`, `priority`, `sort_order`, `created_at`, `updated_at`) VALUES
(13, 1, 'Сердце-убежище', 'Вы любите так, что рядом становится легче дышать. Ваше чувство проявляется не в громких жестах, а в тепле, внимании и ощущении: здесь не нужно заслуживать право быть собой.', NULL, 50, 10, '2026-04-13 20:29:10', '2026-04-13 20:29:10'),
(14, 1, 'Искра-приключение', 'Для вас любовь жива, когда в ней есть движение, смех и немного риска. Вы вносите в отношения импульс, игру и ощущение, что вдвоем мир можно проживать ярче.', NULL, 35, 20, '2026-04-13 20:29:10', '2026-04-13 20:29:10'),
(15, 1, 'Глубокая романтика', 'Вам важна не просто симпатия, а тонкая эмоциональная связь. Вы чувствуете полутона, храните особенные моменты и ищете любовь, которую хочется не объяснять, а проживать.', NULL, 45, 30, '2026-04-13 20:29:10', '2026-04-13 20:29:10'),
(16, 1, 'Надежная опора', 'Вы выбираете отношения, в которых есть устойчивость, ясность и взрослая взаимность. Для вас любовь подтверждается поступками, договоренностями и умением быть рядом не только в легком.', NULL, 60, 40, '2026-04-13 20:29:10', '2026-04-13 20:29:10'),
(17, 1, 'Честная близость', 'Вам особенно важна искренность. Вы тянетесь к тем отношениям, где можно говорить правду без масок, обсуждать сложное и не делать вид, будто ничего не происходит.', NULL, 55, 50, '2026-04-13 20:29:10', '2026-04-13 20:29:10'),
(18, 1, 'Нежная свобода', 'Вы любите бережно и без захвата чужого пространства. Для вас близость не отменяет личный ритм, границы и право каждого оставаться собой.', NULL, 40, 60, '2026-04-13 20:29:10', '2026-04-13 20:29:10'),
(19, 2, 'Ясное солнце', 'Вы приносите в пространство ясность, контакт и ощущение, что многое можно пережить проще. С вами часто становится легче дышать, думать и собираться.', NULL, 60, 10, '2026-04-13 20:29:10', '2026-04-13 20:29:10'),
(20, 2, 'Мягкий дождь', 'Вы тонко чувствуете людей и умеете создавать мягкую атмосферу. Рядом с вами проще говорить честно, оттаивать и не притворяться сильнее, чем есть на самом деле.', NULL, 55, 20, '2026-04-13 20:29:10', '2026-04-13 20:29:10'),
(21, 2, 'Туманный рассвет', 'В вас много нюансов, наблюдательности и глубины. Вы не раскрываетесь с первой минуты, но именно в этой тишине и полутоне рождается ваша притягательность.', NULL, 45, 30, '2026-04-13 20:29:10', '2026-04-13 20:29:10'),
(22, 2, 'Гроза энергии', 'Вы входите в пространство как заряд. В вас много силы, характера и живого напряжения, которое будит других и редко остается незамеченным.', NULL, 35, 40, '2026-04-13 20:29:10', '2026-04-13 20:29:10'),
(23, 2, 'Ветер перемен', 'Вы несете движение, свежесть и ощущение нового поворота. С вами жизнь не застывает, потому что вы чувствуете, когда пора менять ритм, маршрут или саму перспективу.', NULL, 40, 50, '2026-04-13 20:29:10', '2026-04-13 20:29:10'),
(24, 2, 'Тихий снег', 'В вашей энергии есть сдержанность, чистота и редкая форма спокойствия. Вы умеете не шуметь, но именно этим создаете вокруг себя пространство, где все становится тише и честнее.', NULL, 50, 60, '2026-04-13 20:29:10', '2026-04-13 20:29:10'),
(25, 3, 'Уютный slow vibe', 'Сегодня вам ближе мягкий режим жизни: комфорт, простые радости, спокойный ритм и право не ускоряться ради чужой спешки. Ваш вайб про бережность к себе.', NULL, 55, 10, '2026-04-13 20:29:10', '2026-04-13 20:29:10'),
(26, 3, 'Городской драйв', 'Сейчас вы на частоте движения: встречи, маршрут, темп, ощущение, что день идет вперед и набирает скорость. Ваш вайб про живую включенность в мир.', NULL, 35, 20, '2026-04-13 20:29:10', '2026-04-13 20:29:10'),
(27, 3, 'Творческий поток', 'Сегодня у вас состояние, в котором идеи, образы и настроение важны не меньше плана. Вам нужен день, где можно не только делать, но и чувствовать форму, стиль и вдохновение.', NULL, 50, 30, '2026-04-13 20:29:10', '2026-04-13 20:29:10'),
(28, 3, 'Ночной интроверт', 'Ваш ресурс сейчас в тишине, дистанции и внутреннем пространстве. Это не про холод, а про точную настройку: меньше лишнего, больше настоящего контакта с собой.', NULL, 45, 40, '2026-04-13 20:29:10', '2026-04-13 20:29:10'),
(29, 3, 'Игривый импульс', 'Сегодня вам идет легкость, спонтанность и маленькое разрешение жить без лишней серьезности. Ваш вайб про живую искру, шутку и движение из желания, а не из долга.', NULL, 40, 50, '2026-04-13 20:29:10', '2026-04-13 20:29:10'),
(30, 3, 'Собранный фокус', 'Сейчас вы сильнее всего в ясности, структуре и чувстве контроля над днем. Ваш вайб про точность, завершение важного и удовольствие от внутренней собранности.', NULL, 60, 60, '2026-04-13 20:29:10', '2026-04-13 20:29:10');
